const WINDOWS_PATH =
  'M0 0h121.329v121.329H0zm134.671 0H256v121.329H134.671zM0 134.671h121.329V256H0zm134.671 0H256V256H134.671z';

const MIKU_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="#2da8a8" d="M6.2 4.2 3.1 12.6c-.7 2-.5 4.8 1.2 6.4 1.2 1.1 3 .7 4.2-.2-.5-2.6-.7-5.5-.1-8.2l1.8-4.2-4-2.2Zm11.6 0-4 2.2 1.8 4.2c.6 2.7.4 5.6-.1 8.2 1.2.9 3 1.3 4.2.2 1.7-1.6 1.9-4.4 1.2-6.4L17.8 4.2Z"/><circle cx="12" cy="11.5" r="5.3" fill="#fdeee5"/><path fill="#2da8a8" d="M6.7 10.6c.2-3.4 2.5-5.6 5.3-5.6s5.1 2.2 5.3 5.6c-1.4-1.2-2.7-2.2-3.7-3.4-.6 1.5-1.5 2.7-2.8 3.4-.5-.8-.9-1.7-1.1-2.6-.9.9-1.9 1.8-3 2.6Z"/><path fill="#d02678" d="M5.7 5.2 7.6 4l1.1 2-1.9 1.2-1.1-2Zm12.6 0L16.4 4l-1.1 2 1.9 1.2 1.1-2Z"/><circle cx="10.1" cy="12.1" r=".85" fill="#1e8e99"/><circle cx="13.9" cy="12.1" r=".85" fill="#1e8e99"/></svg>`;

export function toServerIconSource(
  server:
    | ServerIconSource
    | Pick<
        ServerSummaryRecord,
        'id' | 'name' | 'kind' | 'osLabel' | 'platform' | 'release' | 'distribution' | 'osName'
      >,
): ServerIconSource {
  if ('host' in server && server.host !== undefined) return server;
  const summary = server as Partial<ServerSummaryRecord>;
  return {
    id: summary.id,
    name: summary.name,
    kind: summary.kind,
    osLabel: summary.osLabel,
    platform: summary.platform,
    host: {
      platform: summary.platform ?? null,
      release: summary.release ?? null,
      distribution: summary.distribution ?? null,
      osName: summary.osName ?? summary.osLabel ?? null,
    },
  };
}

function BrandPathGlyph({
  d,
  viewSize = 24,
  size,
}: {
  readonly d: string;
  readonly viewSize?: number;
  readonly size: number;
}) {
  const { theme } = useHausUi();
  const fill = resolveColorToCss(colorToken('textPrimary'), theme, false);
  return (
    <VectorGraphic
      viewWidth={viewSize}
      viewHeight={viewSize}
      width={size}
      height={size}
      fill={fill}
      ariaHidden
      style={{ layout: { width: px(size), height: px(size), flexShrink: 0 } }}
      paths={[{ d, fill }]}
    />
  );
}

/** Cross-platform OS / distro / hardware glyph matching Electron's `ServerIcon`. */
export function ServerDistroIcon({
  server,
  icon,
  size = 20,
}: {
  readonly server:
    | ServerIconSource
    | Pick<
        ServerSummaryRecord,
        | 'id'
        | 'name'
        | 'kind'
        | 'icon'
        | 'osLabel'
        | 'platform'
        | 'release'
        | 'distribution'
        | 'osName'
      >;
  readonly icon?: string;
  readonly size?: number;
}) {
  const override = icon ?? ('icon' in server ? server.icon : undefined);
  const resolved = resolveServerIcon(toServerIconSource(server), override);

  if (resolved === 'miku') {
    return (
      <VectorGraphic
        viewWidth={24}
        viewHeight={24}
        width={size}
        height={size}
        rawSvgMarkup={MIKU_SVG}
        ariaHidden
        style={{ layout: { width: px(size), height: px(size), flexShrink: 0 } }}
      />
    );
  }
  if (resolved === 'windows') {
    return <BrandPathGlyph d={WINDOWS_PATH} viewSize={256} size={size} />;
  }
  const brandPath = BRAND_VECTOR_PATHS[resolved];
  if (brandPath) {
    return <BrandPathGlyph d={brandPath} size={size} />;
  }

  const lucideMap: Partial<Record<ServerIconId, UiIconName>> = {
    desktop: 'monitor',
    laptop: 'laptop',
    nas: 'database',
    storage: 'hard-drive',
    server: 'server',
  };
  return <UiIcon name={lucideMap[resolved] ?? 'server'} size={size} />;
}

/** Cross-platform service runtime badge icon (`Docker`, `PM2`, or OS distro for `System`). */
export function ServiceManagerBadgeIcon({
  kind,
  server,
  size = 18,
}: {
  readonly kind: ServerServiceManager;
  readonly server: Pick<
    ServerSummaryRecord,
    'id' | 'name' | 'kind' | 'osLabel' | 'platform' | 'release' | 'distribution' | 'osName'
  >;
  readonly size?: number;
}) {
  if (kind === 'systemServices') {
    // Use OS-detected icon rather than manual user hardware override, matching Electron's `ServerIcon({ host })`.
    return (
      <ServerDistroIcon
        server={{
          osLabel: server.osLabel,
          platform: server.platform,
          host: {
            platform: server.platform ?? null,
            release: server.release ?? null,
            distribution: server.distribution ?? null,
            osName: server.osName ?? server.osLabel ?? null,
          },
        }}
        size={size}
      />
    );
  }
  const d = kind === 'docker' ? BRAND_VECTOR_PATHS.docker : BRAND_VECTOR_PATHS.pm2;
  return <BrandPathGlyph d={d ?? ''} size={size} />;
}

/** Cross-platform disk / partition / media / bus icon matching Electron's `DiskIcon`. */
export function ServerDiskGlyph({
  disk,
  size = 18,
}: {
  readonly disk: ServerDiskRecord;
  readonly size?: number;
}) {
  const iconName: UiIconName =
    disk.type === 'partition'
      ? 'columns-3'
      : disk.type === 'container'
        ? 'layers'
        : disk.type === 'volume' || (disk.kind === 'volume' && !disk.type)
          ? 'database'
          : disk.mediaKind === 'sd' || disk.mediaKind === 'mmc'
            ? 'card-sim'
            : disk.mediaKind === 'optical'
              ? 'disc-3'
              : disk.mediaKind === 'flash' || (!disk.mediaKind && disk.transport === 'usb')
                ? 'usb'
                : 'hard-drive';
  return <UiIcon name={iconName} size={size} />;
}

/** Cross-platform distro & hardware icon picker matching Electron's `ServerIconPicker`. */
export function ServerIconPicker({
  server,
  value,
  disabled = false,
  onChange,
}: {
  readonly server: ServerSummaryRecord;
  readonly value?: ServerIconId;
  readonly disabled?: boolean;
  readonly onChange: (next: ServerIconId | undefined) => void;
}) {
  const [expanded, setExpanded] = useState(false);
  const automaticIcon = resolveServerIcon(toServerIconSource(server));
  const automaticLabel = serverIconOptions.find((opt) => opt.id === automaticIcon)?.label;
  const selectedLabel = value
    ? (serverIconOptions.find((opt) => opt.id === value)?.label ?? value)
    : `Automatic${automaticLabel ? ` · ${automaticLabel}` : ''}`;

  return (
    <Stack gapPx={8} style={{ layout: { width: pct(100) } }}>
      <Text size={12} weight={500}>
        Icon
      </Text>
      <Row align="center" gapPx={10} wrap style={{ layout: { width: pct(100) } }}>
        <Pressable
          id="server-icon-picker-trigger"
          disabled={disabled}
          ariaExpanded={expanded}
          onActivate={() => setExpanded((prev) => !prev)}
          style={{
            layout: {
              display: 'flex',
              direction: 'row',
              alignItems: 'center',
              gap: px(10),
              padding: insets(9, 14),
              flexGrow: 1,
              minWidth: px(220),
              position: 'relative',
              overflow: 'hidden',
            },
            material: new SolidMaterial(colorToken('soft')),
            border: { width: 1, color: colorToken('border') },
            corners: corners(14),
          }}
        >
          <ServerDistroIcon server={server} icon={value ?? ''} size={22} />
          <Text size={12.5} weight={500} style={{ layout: { flexGrow: 1 } }}>
            {selectedLabel}
          </Text>
          <UiIcon name={expanded ? 'chevron-up' : 'chevron-down'} size={15} />
        </Pressable>

        {value && (
          <Pressable
            id="server-icon-picker-reset"
            disabled={disabled}
            onActivate={() => onChange(undefined)}
            style={{
              layout: {
                display: 'flex',
                direction: 'row',
                alignItems: 'center',
                gap: px(6),
                padding: insets(9, 12),
              },
              material: new SolidMaterial(colorToken('soft')),
              border: { width: 1, color: colorToken('border') },
              corners: corners(12),
            }}
          >
            <UiIcon name="rotate-ccw" size={13} />
            <Text size={11.5} tone="muted" weight={500}>
              Use automatic
            </Text>
          </Pressable>
        )}
      </Row>

      {expanded && (
        <Grid
          columns={3}
          minColumnWidthPx={150}
          gapPx={6}
          style={{
            layout: { width: pct(100), padding: insets(8) },
            material: new SolidMaterial(colorToken('soft')),
            border: { width: 1, color: colorToken('border') },
            corners: corners(16),
          }}
        >
          <Pressable
            ariaPressed={!value}
            disabled={disabled}
            onActivate={() => onChange(undefined)}
            style={{
              layout: {
                display: 'flex',
                direction: 'row',
                alignItems: 'center',
                gap: px(8),
                padding: insets(8, 10),
                position: 'relative',
                overflow: 'hidden',
              },
              material: new SolidMaterial(!value ? colorToken('card') : transparentColor),
              border: { width: 0, style: 'none', color: transparentColor },
              corners: corners(11),
            }}
          >
            <ServerDistroIcon server={{ ...server, icon: undefined }} size={18} />
            <Text size={11.5} weight={!value ? 600 : 500} style={{ layout: { flexGrow: 1 } }}>
              Automatic
            </Text>
            {!value && <UiIcon name="check" size={13} />}
            {!value && <GlassRim preset="control" radiusPx={10} opacity={0.55} />}
          </Pressable>

          {serverIconOptions.map((option) => {
            const active = value === option.id;
            return (
              <Pressable
                key={option.id}
                ariaPressed={active}
                disabled={disabled}
                onActivate={() => onChange(option.id)}
                style={{
                  layout: {
                    display: 'flex',
                    direction: 'row',
                    alignItems: 'center',
                    gap: px(8),
                    padding: insets(8, 10),
                    position: 'relative',
                    overflow: 'hidden',
                  },
                  material: new SolidMaterial(active ? colorToken('card') : transparentColor),
                  border: { width: 0, style: 'none', color: transparentColor },
                  corners: corners(11),
                }}
              >
                <ServerDistroIcon server={server} icon={option.id} size={18} />
                <Text size={11.5} weight={active ? 600 : 500} style={{ layout: { flexGrow: 1 } }}>
                  {option.label}
                </Text>
                {active && <UiIcon name="check" size={13} />}
                {active && <GlassRim preset="control" radiusPx={10} opacity={0.55} />}
              </Pressable>
            );
          })}
        </Grid>
      )}

      <Text size={11} tone="muted">
        Automatic follows the server identity and operating system.
      </Text>
    </Stack>
  );
}
